class Solution {
    public int removeDuplicates(int[] nums) {
        List<Integer> unique = new ArrayList<>();
        unique.add(nums[0]);

        for(int i = 1; i < nums.length; i++) {
            if(nums[i] != nums[i - 1]) {
                unique.add(nums[i]);
            }
        }

